(() => {
  const initial = () => ({ day:1, actions:3, approval:58, economy:54, stability:62, trust:57, capital:62, budget:82, house:51, senate:49, policies:[], bills:{infrastructure:0,care:0,climate:0}, passed:[], relations:{Canada:72,Japan:66,France:63,India:58}, visited:[], trend:0, ended:false, history:[58], lastEventDay:0 });
  let state = loadGame() || initial();
  const $ = id => document.getElementById(id);
  const clamp = n => Math.max(0, Math.min(100, Math.round(n)));
  const pad = n => String(n).padStart(2,'0');
  const countries = [
    {name:'Canada',flag:'🇨🇦',distance:'1.5 HRS',desc:'A vital neighbor and trusted partner. Clean energy and trade top the agenda.',topic:'Cross-border clean energy',rel:72},
