  function toast(text){const el=$('toast');el.textContent=text;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2800)}
  function costAction(amount=1){ if(state.ended) return false; if(state.actions<amount){toast('Your schedule is full. End the day to continue.');return false} state.actions-=amount; return true }
  function apply(effects){Object.entries(effects).forEach(([key,value])=>{if(key==='budget')state.budget=Math.max(0,state.budget+value);else if(key in state)state[key]=clamp(state[key]+value)});state.trend=state.approval-58}
  function openModal({eyebrow='PRESIDENTIAL DECISION',title,copy,options}){
