  function navigate(view){document.querySelectorAll('.view').forEach(el=>el.classList.toggle('active',el.id===`view-${view}`));document.querySelectorAll('.nav-item').forEach(el=>el.classList.toggle('active',el.dataset.view===view));$('top-section').textContent=({overview:'SITUATION ROOM',agenda:'DAILY AGENDA',policy:'POLICY DESK',congress:'THE PEOPLE\'S HOUSE',world:'WORLD AFFAIRS'})[view]||'SITUATION ROOM';$('sidebar').classList.remove('open');window.scrollTo({top:0,behavior:'smooth'});render()}
  function attendMeeting(kind){if(!costAction())return;const meetings={briefing:{title:'The intelligence briefing',copy:'Your national security team brings three items forward. What should get your attention?',options:[['Focus on cyber readiness','Prepare essential services for emerging threats. +3 stability, −2 capital.','cyber'],['Ask for a diplomatic readout','Lead with context and keep channels open. +2 stability, +2 trust.','readout'],['Request a public safety review','Bring the briefing back to people’s everyday lives. +2 trust.','safety']]},leaders:{title:'In the room with Congress',copy:'Both parties are ready to hear from you. The opening move is yours.',options:[['Find shared ground','Invite both sides to shape a practical first bill. +4 house, +3 senate, +4 capital.','shared'],['Make the case for bold action','Rally supporters around an ambitious agenda. +4 approval, +2 house, −4 capital.','bold'],['Listen before you lead','Ask leaders what their constituents need most. +3 trust, +2 senate, +3 capital.','listen']]},community:{title:'Community voices',copy:'Parents, teachers, and small business owners are here to tell you what they need.',options:[['Put their stories first','Make a commitment to listen before deciding. +4 trust, +2 approval.','stories'],['Bring their ideas to the policy desk','Turn local insight into national priorities. +3 trust, +3 capital.','ideas'],['Invite them to a town hall','Keep the conversation going across the country. +2 trust, +2 approval.','townhall']]}};const m=meetings[kind];openModal({title:m.title,copy:m.copy,options:m.options.map(([title,detail,id])=>({title,detail,action:()=>{const fx={};if(id==='cyber')Object.assign(fx,{stability:3,capital:-2});if(id==='readout')Object.assign(fx,{stability:2,trust:2});if(id==='safety')Object.assign(fx,{trust:2});if(id==='shared')Object.assign(fx,{house:4,senate:3,capital:4});if(id==='bold')Object.assign(fx,{approval:4,house:2,capital:-4});if(id==='listen')Object.assign(fx,{trust:3,senate:2,capital:3});if(id==='stories')Object.assign(fx,{trust:4,approval:2});if(id==='ideas')Object.assign(fx,{trust:3,capital:3});if(id==='townhall')Object.assign(fx,{trust:2,approval:2});apply(fx);toast(`${m.title} concluded. Your team is moving on it.`);render()}}))})}
  function launchPolicy(id){const p=policies.find(x=>x.id===id);if(state.policies.includes(id)){toast('This priority is already part of your agenda.');return}if(state.capital<p.cost){toast('Not enough political capital. Build support with a meeting or coalition.');return}if(state.budget<p.budget){toast('The treasury cannot support this commitment yet.');return}if(!costAction())return;openModal({eyebrow:'SET A NATIONAL PRIORITY',title:`Launch: ${p.title}?`,copy:`This is a clear commitment to ${p.desc.toLowerCase()} It will require $${p.budget}B and ${p.cost} political capital to get started.`,options:[{title:'Make it a priority',detail:`Invest $${p.budget}B · ${p.cost} political capital · uses 1 action`,action:()=>{state.policies.push(id);state.capital-=p.cost;state.budget-=p.budget;apply(p.effects);toast(`${p.title} is now an official White House priority.`);render()}},{title:'Not today',detail:'Keep your options open.'}]})}
  function lobbyBill(id){const b=billData.find(x=>x.id===id);if(state.bills[id]>=100){toast('This bill has already passed.');return}if(state.capital<4){toast('You need at least 4 political capital to make your case.');return}if(!costAction())return;openModal({eyebrow:'MAKE THE CASE ON CAPITOL HILL',title:`Move the ${b.title}`,copy:'Your legislative affairs team has lined up key conversations. Pick a pitch that could bring more lawmakers on board.',options:[{title:'Lead with local jobs',detail:'Invest in the communities lawmakers represent. +30% progress, +3 House support.',action:()=>progressBill(id,30,3,0)},{title:'Build a cross-party coalition',detail:'Offer a practical compromise. +22% progress, +2 House, +2 Senate.',action:()=>progressBill(id,22,2,2)},{title:'Make the public case',detail:'Bring constituents into the conversation. +18% progress, +3 approval.',action:()=>{progressBill(id,18,0,0);apply({approval:3})}}]})}
  function progressBill(id,progress,house,senate){state.capital=Math.max(0,state.capital-4);state.bills[id]=Math.min(100,state.bills[id]+progress);state.house=clamp(state.house+house);state.senate=clamp(state.senate+senate);const b=billData.find(x=>x.id===id);if(state.bills[id]>=100&&state.house>=50&&state.senate>=50){state.passed.push(id);state.budget=Math.max(0,state.budget-4);apply({trust:5,approval:3,stability:2});toast(`${b.title} passed both chambers and is now law!`)}else if(state.bills[id]>=100){state.bills[id]=90;toast('The bill is ready for a final vote. Secure majority support in both chambers.')}else toast(`Negotiations moved ${b.title} forward.`);render()}
  function meetLeaders(){attendMeeting('leaders')}
  function travel(name){const c=countries.find(x=>x.name===name);if(state.budget<3){toast('There is not enough travel funding for a presidential visit.');return}if(!costAction(2))return;openModal({eyebrow:'PRESIDENTIAL TRAVEL · 2 ACTIONS',title:`A visit to ${c.name}`,copy:`A presidential visit sends a message. The agenda: ${c.topic.toLowerCase()}. Choose how to use your time together.`,options:[{title:'Sign a practical partnership',detail:`Build trust and trade ties. +10 relationship, +2 stability, −$3B.`,action:()=>finishTravel(c,{relation:10,stability:2,budget:-3,approval:1})},{title:'Listen and learn',detail:'Deepen the relationship with an open exchange. +14 relationship, +3 trust, −$2B.',action:()=>finishTravel(c,{relation:14,trust:3,budget:-2})},{title:'Address a joint press conference',detail:'Show unity to both publics. +8 relationship, +3 approval, −$3B.',action:()=>finishTravel(c,{relation:8,approval:3,budget:-3})}]})}
  function finishTravel(c,fx){state.relations[c.name]=clamp((state.relations[c.name]??c.rel)+fx.relation);delete fx.relation;apply(fx);if(!state.visited.includes(c.name))state.visited.push(c.name);toast(`The visit to ${c.name} strengthened the relationship.`);render()}
  function chooseEvent(event){openModal({eyebrow:'BREAKING · DAY '+pad(state.day),title:event.title,copy:event.copy,options:event.options.map(([title,detail,id])=>({title,detail,action:()=>{if(id==='listen')apply({trust:3,approval:2});if(id==='announce')apply({approval:2,capital:-2});if(id==='coalition')apply({stability:3,capital:2});if(id==='aid')apply({stability:4,budget:-5});if(id==='coordinate')apply({trust:3,budget:-2});if(id==='assess')apply({capital:2});if(id==='diplomacy')apply({stability:4});if(id==='statement')apply({trust:3,stability:-2});if(id==='envoys')apply({stability:3,capital:2});state.lastEventDay=state.day;toast('The country has heard your decision.');render()}}))})}
  function nextDay(){if(state.ended){showFinal();return}if(state.day>=100){finishGame();return}state.day++;state.actions=3;state.economy=clamp(state.economy+(state.policies.includes('jobs')?0.35:0));state.stability=clamp(state.stability+(state.passed.length?0.2:0));if(state.day%7===0){state.capital=clamp(state.capital+2);state.budget=Math.max(0,state.budget+1)}if(state.day%5===0&&state.lastEventDay!==state.day){const event=dayEvents[(Math.floor(state.day/5)-1)%dayEvents.length];render();chooseEvent(event);return}state.history.push(state.approval);if(state.history.length>7)state.history.shift();toast(`Day ${pad(state.day)} begins. Three new actions await.`);render();if(state.day===100)finishGame()}
  function finishGame(){state.ended=true;render();showFinal()}
  function showFinal(){const score=Math.round((state.approval+state.economy+state.stability+state.trust)/4);const title=score>=70?'A mandate for the future':score>=55?'A nation moving forward':'A presidency tested';openModal({eyebrow:'THE FIRST 100 DAYS · COMPLETE',title,copy:`${title}. Your administration finishes with ${score}/100 across public approval, prosperity, stability, and trust. You signed ${state.passed.length} law${state.passed.length===1?'':'s'}, launched ${state.policies.length} national priorities, and visited ${state.visited.length} partner nation${state.visited.length===1?'':'s'}. Every choice left its mark.`,options:[{title:'Begin a new administration',detail:'Start a fresh simulation from inauguration day.',action:()=>{state=initial();localStorage.removeItem('presidency-save');render();navigate('overview');toast('A new term begins. The country is yours to lead.')}}]})}

  function renderMetrics(){const defs=[['PUBLIC APPROVAL','approval','%', '↗','Approval among voters'],['ECONOMY','economy','/100','◒','Business confidence'],['NATIONAL STABILITY','stability','/100','⌑','Safety & resilience'],['PUBLIC TRUST','trust','/100','♡','Confidence in leadership']];$('metrics-grid').innerHTML=defs.map(([label,key,unit,icon,foot])=>`<div class="metric-card"><div class="metric-top"><span class="metric-label">${label}</span><span class="metric-symbol">${icon}</span></div><div class="metric-value">${state[key]}<small>${unit}</small></div><span class="metric-foot ${state.trend>=0?'up':''}">${key==='approval'?(state.trend>=0?'+':'')+state.trend+' pts':foot}</span></div>`).join('');$('approval-big').textContent=state.approval;$('approval-trend').textContent=(state.trend>=0?'+':'')+state.trend;$('day-label').textContent=pad(state.day);$('side-day').textContent=pad(state.day);$('chart-day').textContent=pad(state.day);$('brief-date').textContent=dayDate(state.day).short;$('agenda-date').textContent=dayDate(state.day).full.toUpperCase();$('action-counter').textContent=`${state.actions} ACTION${state.actions===1?'':'S'} LEFT`;$('advance-button').innerHTML=state.ended?'See your legacy <span>→</span>':'Advance the day <span>→</span>';$('advance-button-agenda').innerHTML=state.ended?'See your legacy <span>→</span>':'End day <span>→</span>';
    const chartPoints=state.history.concat(state.approval);const line=chartPoints.map((v,i)=>`${i?'L':'M'}${(i/(Math.max(1,chartPoints.length-1)))*420} ${140-(v-35)*2.8}`).join(' ');const area=`${line} L420 150 L0 150Z`;$('chart-line').setAttribute('d',line);$('chart-area').setAttribute('d',area);const y=140-(state.approval-35)*2.8;document.querySelector('.chart-dot').setAttribute('cy',y);document.querySelector('.chart-dot').setAttribute('cx',420);
    $('pending-count').textContent=pad(3-state.policies.length>0?Math.max(0,3-state.policies.length):0);
  }
  function dayDate(day){const d=new Date(Date.UTC(2025,0,20+(day-1)));const full=new Intl.DateTimeFormat('en-US',{weekday:'long',month:'long',day:'numeric',timeZone:'UTC'}).format(d);const short=new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',timeZone:'UTC'}).format(d).toUpperCase();return{full,short}}
  function renderSchedule(){const rows=agendaTemplates.map((a,i)=>`<div class="schedule-row"><span class="schedule-time">${a.time}</span><span class="schedule-marker"></span><span class="schedule-text">${a.title}</span><span class="schedule-status">${i===0?'BRIEFING':'ON YOUR CALENDAR'}</span></div>`).join('');$('schedule-list').innerHTML=rows;const agenda=agendaTemplates.map(a=>`<div class="agenda-card"><span class="agenda-card-time">${a.time}</span><span class="agenda-card-icon">${a.icon}</span><div class="agenda-card-copy"><h3>${a.title}</h3><p>${a.description}</p></div><button data-meeting="${a.kind}" ${state.actions<1||state.ended?'disabled':''}>Attend meeting</button></div>`).join('');$('agenda-list').innerHTML=agenda;document.querySelectorAll('[data-meeting]').forEach(btn=>btn.addEventListener('click',()=>attendMeeting(btn.dataset.meeting)));$('chief-note').textContent=state.day===1?'“The first impression is the one you get to make. Let’s make it count.”':state.approval>65?'“People are feeling hopeful. Let’s turn that optimism into progress.”':state.capital<20?'“We need a little more room to maneuver. A listening session could help.”':'“Every day is a chance to show people what steady leadership looks like.”'}
  function renderDecisions(){const items=[{icon:'◈',title:'Choose your first priority',sub:state.policies.length?'Your agenda is taking shape':'Policy desk · Set an agenda',click:()=>navigate('policy')},{icon:'⌂',title:'Build a bridge on the Hill',sub:state.passed.length?`${state.passed.length} bill${state.passed.length===1?'':'s'} passed`:'Congress · Find common ground',click:()=>navigate('congress')},{icon:'◎',title:'Connect with a world leader',sub:state.visited.length?`${state.visited.length} diplomatic visit${state.visited.length===1?'':'s'} completed`:'Diplomacy · Travel abroad',click:()=>navigate('world')}];$('decision-list').innerHTML=items.map((x,i)=>`<div class="decision-item"><span class="decision-icon">${x.icon}</span><span class="decision-copy"><b>${x.title}</b><small>${x.sub}</small></span><button class="decision-arrow" data-decision="${i}" aria-label="${x.title}">→</button></div>`).join('');document.querySelectorAll('[data-decision]').forEach((btn,i)=>btn.addEventListener('click',items[i].click));$('priority-title').textContent=state.day===1?'A fresh start, a full agenda':state.policies.length?`${policies.find(p=>p.id===state.policies[state.policies.length-1]).title} is underway`:'A nation in motion';$('priority-copy').textContent=state.day===1?'Your new administration begins with a rare opportunity: set the tone before the first hundred days gather speed.':state.policies.length?'Your team is turning your priorities into a plan. The country will be watching for results.':'The first hundred days are moving quickly. Build support, listen closely, and choose where to lead.'}
  function renderPolicies(){ $('policy-cards').innerHTML=policies.map(p=>{const selected=state.policies.includes(p.id);return `<article class="policy-card ${selected?'selected':''}"><span class="policy-icon">${p.icon}</span><h3>${p.title}</h3><p>${p.desc}</p><div class="policy-meta"><span>${p.label}</span><b>$${p.budget}B · ${p.cost} CAPITAL</b></div><button data-policy="${p.id}" ${selected||state.ended?'disabled':''}>${selected?'✓ PRIORITY LAUNCHED':'Make this a priority'}</button></article>`}).join('');document.querySelectorAll('[data-policy]').forEach(btn=>btn.addEventListener('click',()=>launchPolicy(btn.dataset.policy)));$('capital-value').textContent=state.capital;$('capital-bar').style.width=`${state.capital}%`;$('mandate-stats').innerHTML=`<div class="mandate-stat"><span>Public approval</span><b>${state.approval}%</b></div><div class="mandate-stat"><span>National priorities</span><b>${state.policies.length} launched</b></div><div class="mandate-stat"><span>Budget available</span><b>$${state.budget}B</b></div>`;renderBills('bill-list',false)}
  function renderBills(target,congress){const html=billData.map(b=>{const progress=state.bills[b.id];const passed=state.passed.includes(b.id);return `<div class="bill-card"><span class="bill-icon">${passed?'✓':b.icon}</span><div class="bill-copy"><h3>${b.title}</h3><p>${passed?'Signed into law · delivering results':b.desc}</p></div><div class="bill-progress"><div class="progress-track"><i style="width:${progress}%"></i></div><small>${passed?'PASSED':progress?`${progress}% · IN COMMITTEE`:'INTRODUCED'}</small></div><button class="bill-action" data-bill="${b.id}" ${passed||state.ended?'disabled':''}>${passed?'✓ LAW':congress?'Lobby':'Build support'}</button></div>`}).join('');$(target).innerHTML=html;$(target).querySelectorAll('[data-bill]').forEach(btn=>btn.addEventListener('click',()=>lobbyBill(btn.dataset.bill)))}
  function renderCongress(){ $('house-support').textContent=state.house;$('senate-support').textContent=state.senate;renderBills('congress-bills',true);$('meet-leaders').disabled=state.actions<1||state.ended;$('meet-leaders').onclick=meetLeaders}
  function renderWorld(){ $('world-relationship').innerHTML=countries.map(c=>`<div class="relationship-row"><span class="country-flag">${c.flag}</span><span class="relationship-copy"><b>${c.name}</b><small>${state.visited.includes(c.name)?'RECENT VISIT':'DIPLOMATIC PARTNER'}</small></span><span class="relation-value">${state.relations[c.name]??c.rel}%</span></div>`).join('');$('country-grid').innerHTML=countries.map(c=>`<article class="country-card"><div class="country-top"><span class="country-flag-big">${c.flag}</span><span class="country-distance">${c.distance} FLIGHT</span></div><h3>${c.name}</h3><p>${c.desc}</p><div class="country-footer"><span class="country-relation">${state.relations[c.name]??c.rel}% RELATIONS</span><button data-travel="${c.name}" ${state.actions<2||state.ended?'disabled':''}>${state.visited.includes(c.name)?'Visit again':'Plan a visit'} →</button></div></article>`).join('');document.querySelectorAll('[data-travel]').forEach(btn=>btn.addEventListener('click',()=>travel(btn.dataset.travel)))}
  function render(){renderMetrics();renderSchedule();renderDecisions();renderPolicies();renderCongress();renderWorld();$('clock').textContent=state.day===1?'09:41 AM':'09:41 AM';if(state.ended){$('advance-button').textContent='See your legacy →';$('advance-button-agenda').textContent='See your legacy →'}document.title=`DAY ${pad(state.day)} — THE PRESIDENCY`}
  document.querySelectorAll('.nav-item').forEach(btn=>btn.addEventListener('click',()=>navigate(btn.dataset.view)));
  document.querySelectorAll('[data-goto]').forEach(btn=>btn.addEventListener('click',()=>navigate(btn.dataset.goto)));
  $('advance-button').addEventListener('click',()=>state.ended?showFinal():nextDay());$('advance-button-agenda').addEventListener('click',()=>state.ended?showFinal():nextDay());$('save-button').addEventListener('click',save);$('modal-close').addEventListener('click',closeModal);$('modal-backdrop').addEventListener('click',e=>{if(e.target===$('modal-backdrop'))closeModal()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});$('menu-toggle').addEventListener('click',()=>$('sidebar').classList.toggle('open'));
  render();
})();

