(() => {
  const initial=()=>({day:1,actions:3,approval:58,economy:54,stability:62,trust:57,capital:62,budget:82,house:51,senate:49,policies:[],bills:{infrastructure:0,care:0,climate:0},passed:[],relations:{Canada:72,Japan:66,France:63,India:58},visited:[],trend:0,ended:false,history:[58],lastEventDay:0});
  let state;try{state=JSON.parse(localStorage.getItem('presidency-save'))||initial()}catch{state=initial()}
  const $=id=>document.getElementById(id),clamp=n=>Math.max(0,Math.min(100,Math.round(n))),pad=n=>String(n).padStart(2,'0');
  const countries=[{name:'Canada',flag:'🇨🇦',distance:'1.5 HRS',desc:'A vital neighbor and trusted partner. Clean energy and trade top the agenda.',topic:'Cross-border clean energy',rel:72},{name:'Japan',flag:'🇯🇵',distance:'14 HRS',desc:'A steadfast ally navigating a changing region. Technology and security await.',topic:'Technology & regional security',rel:66},{name:'France',flag:'🇫🇷',distance:'8 HRS',desc:'A founding partner in the transatlantic alliance. Climate and shared values.',topic:'Climate & transatlantic ties',rel:63},{name:'India',flag:'🇮🇳',distance:'16 HRS',desc:'A growing democracy with a bold vision. The next chapter is yours to shape.',topic:'Trade & democratic partnership',rel:58}];
  const policies=[{id:'jobs',icon:'↗',title:'Good jobs, built here',desc:'Invest in skilled trades and domestic manufacturing.',cost:12,effects:{economy:6,approval:3},label:'JOBS & ECONOMY',budget:8},{id:'health',icon:'✚',title:'Care within reach',desc:'Make essential care more affordable for every family.',cost:14,effects:{trust:5,approval:4},label:'HEALTH & FAMILIES',budget:10},{id:'clean',icon:'☼',title:'A cleaner tomorrow',desc:'Accelerate clean energy and resilient communities.',cost:11,effects:{stability:4,economy:2},label:'CLIMATE & ENERGY',budget:7},{id:'schools',icon:'✎',title:'A fair shot for every child',desc:'Give teachers the tools and students the opportunities to thrive.',cost:10,effects:{trust:4,approval:3},label:'EDUCATION',budget:6}];
  const billData=[{id:'infrastructure',title:'American Bridges & Broadband Act',desc:'Repair roads and connect rural communities.',icon:'⌁'},{id:'care',title:'Families First Care Act',desc:'Lower prescription costs and expand local clinics.',icon:'✚'},{id:'climate',title:'Clean Future Investment Act',desc:'Reward clean power and prepare for extreme weather.',icon:'☼'}];
  const agendaTemplates=[{time:'09:00 AM',icon:'◷',title:'Daily intelligence briefing',description:'The President receives an update from national security advisors.',kind:'briefing'},{time:'11:30 AM',icon:'⌂',title:'Bipartisan leadership meeting',description:'A chance to find common ground with congressional leaders.',kind:'leaders'},{time:'02:00 PM',icon:'✦',title:'Community voices at the White House',description:'Hear directly from families and local leaders.',kind:'community'}];
  const events=[{title:'A moment for working families',copy:'A new report puts the squeeze on household budgets in the headlines. Your response will set the tone.',options:[['Visit a community food hub','Connect with families first. +3 trust, +2 approval.','listen'],['Announce a targeted relief review','Show urgency while your team studies the details. +2 approval, −2 capital.','announce'],['Ask for a bipartisan working group','Build a durable answer, even if it takes longer. +3 stability, +2 capital.','coalition']]},{title:'A test of national resilience',copy:'Severe storms have disrupted communities across the coast. Governors are asking for federal support.',options:[['Deploy emergency support','Get help moving now. +4 stability, −$5B.','aid'],['Coordinate with governors','A united response builds confidence. +3 trust, −$2B.','coordinate'],['Request a full damage assessment','Make a careful plan before committing resources. +2 capital.','assess']]},{title:'The world is watching',copy:'A diplomatic dispute has raised tensions between two partners. The calls are waiting on your desk.',options:[['Call both leaders','Lower the temperature through direct diplomacy. +4 stability.','diplomacy'],['Back a joint statement','Stand with allies and make your position clear. +3 trust, −2 stability.','statement'],['Invite envoys to Washington','Open a quiet channel for a lasting solution. +3 stability, +2 capital.','envoys']]}];
  function toast(text){const e=$('toast');e.textContent=text;e.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>e.classList.remove('show'),2600)}
  function save(){localStorage.setItem('presidency-save',JSON.stringify(state));toast('Progress saved. Your administration is right where you left it.')}
  function apply(fx){Object.entries(fx).forEach(([k,v])=>{if(k==='budget')state.budget=Math.max(0,state.budget+v);else if(k in state)state[k]=clamp(state[k]+v)});state.trend=state.approval-58}
  function spend(n=1){if(state.ended)return false;if(state.actions<n){toast('Your schedule is full. End the day to continue.');return false}state.actions-=n;return true}
  function modal({eyebrow='PRESIDENTIAL DECISION',title,copy,options}){$('modal-eyebrow').textContent=eyebrow;$('modal-title').textContent=title;$('modal-copy').textContent=copy;$('modal-options').innerHTML=options.map((o,i)=>`<button class="modal-option" data-opt="${i}"><span><b>${o.title}</b><small>${o.detail}</small></span><span class="option-arrow">→</span></button>`).join('');$('modal-backdrop').hidden=false;document.querySelectorAll('[data-opt]').forEach((b,i)=>b.onclick=()=>{$('modal-backdrop').hidden=true;options[i].action?.()})}
  function closeModal(){$('modal-backdrop').hidden=true}
  function navigate(view){document.querySelectorAll('.view').forEach(e=>e.classList.toggle('active',e.id===`view-${view}`));document.querySelectorAll('.nav-item').forEach(e=>e.classList.toggle('active',e.dataset.view===view));$('top-section').textContent=({overview:'SITUATION ROOM',agenda:'DAILY AGENDA',policy:'POLICY DESK',congress:"THE PEOPLE'S HOUSE",world:'WORLD AFFAIRS'})[view];$('sidebar').classList.remove('open');window.scrollTo({top:0,behavior:'smooth'});render()}
